-- Schema baseline, version 18. GENERATED by `python -m scrap.store.baseline`: do not edit by hand.

CREATE TABLE blob (
    sha256      TEXT PRIMARY KEY,
    mime        TEXT NOT NULL,
    size        INTEGER NOT NULL,
    created_at  TEXT NOT NULL
);

CREATE TABLE page (
    id          TEXT PRIMARY KEY,              -- ULID
    slug        TEXT NOT NULL UNIQUE,
    title       TEXT NOT NULL,
    body        TEXT NOT NULL DEFAULT '',      -- Markdown
    kind        TEXT NOT NULL DEFAULT 'note' CHECK (kind IN ('note', 'todo', 'consume',
                  'whiteboard', 'document')),
    kind_fixed  INTEGER NOT NULL DEFAULT 0 CHECK (kind_fixed IN (0, 1)),  -- 1: the user chose it
    fields      TEXT NOT NULL DEFAULT '{}' CHECK (json_type(fields) = 'object'),  -- flat
    created_at  TEXT NOT NULL,
    updated_at  TEXT NOT NULL,
    deleted_at  TEXT                           -- set: in the trash
, task_done INTEGER NOT NULL DEFAULT 0, task_total INTEGER NOT NULL DEFAULT 0, made_by TEXT NOT NULL DEFAULT 'human' CHECK (made_by IN ('human', 'claude', 'topic', 'gc')));

CREATE TABLE page_rev (
    page_id     TEXT NOT NULL REFERENCES page(id) ON DELETE CASCADE,
    rev         INTEGER NOT NULL,
    title       TEXT NOT NULL,
    body        TEXT NOT NULL,
    author      TEXT NOT NULL,
    created_at  TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'web' CHECK (source IN ('web', 'mcp')),
    PRIMARY KEY (page_id, rev)
);

CREATE TABLE capture (
    id          TEXT PRIMARY KEY,              -- ULID minted by the client: the retry key
    kind        TEXT NOT NULL CHECK (kind IN ('photo', 'note', 'url', 'file')),
    text        TEXT,
    url         TEXT,
    source      TEXT NOT NULL,                 -- 'pwa', 'share', 'mcp'
    author      TEXT NOT NULL,
    created_at  TEXT NOT NULL,                 -- on the device
    received_at TEXT NOT NULL,                 -- on the server
    page_id     TEXT NOT NULL REFERENCES page(id) ON DELETE CASCADE
);

CREATE TABLE capture_blob (
    capture_id  TEXT NOT NULL REFERENCES capture(id) ON DELETE CASCADE,
    ord         INTEGER NOT NULL,
    sha256      TEXT NOT NULL REFERENCES blob(sha256),
    filename    TEXT,
    PRIMARY KEY (capture_id, ord)
);

CREATE TABLE chunk (
    id          INTEGER PRIMARY KEY,
    page_id     TEXT NOT NULL REFERENCES page(id) ON DELETE CASCADE,
    ord         INTEGER NOT NULL,
    text        TEXT NOT NULL
, derived_id INTEGER REFERENCES derived(id) ON DELETE CASCADE, title TEXT NOT NULL DEFAULT '', tags TEXT NOT NULL DEFAULT '', summary TEXT NOT NULL DEFAULT '');

CREATE TABLE tag (
    page_id     TEXT NOT NULL REFERENCES page(id) ON DELETE CASCADE,
    tag         TEXT NOT NULL CHECK (tag = lower(tag) AND length(tag) BETWEEN 1 AND 64),
    PRIMARY KEY (page_id, tag)
);

CREATE TABLE job (
    id            INTEGER PRIMARY KEY,
    kind          TEXT NOT NULL CHECK (kind IN ('ingest', 'refine')),
    capture_id    TEXT NOT NULL REFERENCES capture(id) ON DELETE CASCADE,
    source_sha256 TEXT NOT NULL,               -- the photo
    state         TEXT NOT NULL DEFAULT 'queued'
                    CHECK (state IN ('queued', 'running', 'done', 'dead')),
    failures      INTEGER NOT NULL DEFAULT 0,  -- charged failures (all but pauses): dead at 3
    options       TEXT NOT NULL DEFAULT '{}' CHECK (json_type(options) = 'object'),
    run_after     TEXT NOT NULL,
    last_error    TEXT,
    created_at    TEXT NOT NULL,
    updated_at    TEXT NOT NULL
);

CREATE TABLE queue_state (
    id            INTEGER PRIMARY KEY CHECK (id = 1),
    paused_until  TEXT,                        -- NULL: running
    reason        TEXT CHECK (reason IN ('auth', 'credit', 'outage', 'budget')),
    outages       INTEGER NOT NULL DEFAULT 0,  -- consecutive outage errors: backoff exponent
    notified_at   TEXT,                        -- this pause has been announced
    updated_at    TEXT NOT NULL
);

CREATE TABLE model_run (
    id             INTEGER PRIMARY KEY,
    capture_id     TEXT NOT NULL REFERENCES capture(id) ON DELETE CASCADE,
    source_sha256  TEXT NOT NULL,
    job_id         INTEGER REFERENCES job(id) ON DELETE SET NULL,
    parent_id      INTEGER REFERENCES model_run(id),  -- the turn this one continues (M4)
    purpose        TEXT NOT NULL CHECK (purpose IN ('ingest', 'refine', 'discuss')),
    model          TEXT NOT NULL,              -- requested
    served_model   TEXT,
    prompt_version TEXT NOT NULL,
    sent_sha256    TEXT REFERENCES blob(sha256),  -- the JPEG actually sent, kept for replay
    image_width    INTEGER,                    -- its pixels: the drawing's frame
    image_height   INTEGER,
    request        TEXT NOT NULL CHECK (json_valid(request)),
    response       TEXT CHECK (json_valid(response)),  -- content blocks as returned
    output         TEXT CHECK (json_valid(output)),    -- the sanitised result, with warnings
    usage          TEXT CHECK (json_valid(usage)),
    cost_microusd  INTEGER NOT NULL DEFAULT 0,  -- from usage and a price table
    status         TEXT NOT NULL DEFAULT 'running'
                     CHECK (status IN ('running', 'ok', 'invalid', 'refused', 'error')),
    error_class    TEXT CHECK (error_class IN
                     ('credit', 'auth', 'outage', 'budget', 'timeout', 'invalid', 'content',
                      'image', 'internal', 'crashed')),
    error          TEXT,
    started_at     TEXT NOT NULL,
    finished_at    TEXT
);

CREATE TABLE derived (
    id            INTEGER PRIMARY KEY,
    capture_id    TEXT NOT NULL REFERENCES capture(id) ON DELETE CASCADE,
    source_sha256 TEXT NOT NULL DEFAULT '',
    kind          TEXT NOT NULL CHECK (kind IN
                    ('ocr', 'description', 'summary', 'fetched', 'excalidraw')),
    version       INTEGER NOT NULL CHECK (version >= 1),
    producer      TEXT NOT NULL,               -- model id, or 'human'
    run_id        INTEGER REFERENCES model_run(id),  -- the call that made it; NULL if human
    author        TEXT,                        -- of a human version
    text          TEXT,                        -- indexed while current
    data          TEXT CHECK (json_valid(data)),  -- excalidraw: {"format": ..., "elements": ...}
    superseded_at TEXT,                        -- NULL: the current version
    created_at    TEXT NOT NULL,
    UNIQUE (capture_id, source_sha256, kind, version)
);

CREATE VIRTUAL TABLE chunk_fts USING fts5(
    title, tags, summary, text, content='chunk', content_rowid='id',
    tokenize='porter unicode61'
);

CREATE TABLE page_meta_rev ( id INTEGER PRIMARY KEY AUTOINCREMENT, page_id TEXT NOT NULL REFERENCES page(id) ON DELETE CASCADE, author TEXT NOT NULL, source TEXT NOT NULL CHECK (source IN ('web', 'mcp')), kind_before TEXT NOT NULL, kind_after TEXT NOT NULL, fixed_before INTEGER NOT NULL CHECK (fixed_before IN (0, 1)), fixed_after INTEGER NOT NULL CHECK (fixed_after IN (0, 1)), tags_before TEXT NOT NULL CHECK (json_type(tags_before) = 'array'), tags_after TEXT NOT NULL CHECK (json_type(tags_after) = 'array'), fields_added TEXT NOT NULL DEFAULT '{}'  CHECK (json_type(fields_added) = 'object'), reverts INTEGER REFERENCES page_meta_rev(id), batch_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, fields_was TEXT NOT NULL DEFAULT '{}' CHECK (json_type(fields_was) = 'object'));

CREATE TABLE enrich_job (
    id          INTEGER PRIMARY KEY,
    page_id     TEXT NOT NULL REFERENCES page(id) ON DELETE CASCADE,
    reason      TEXT NOT NULL CHECK (reason IN ('capture', 'save', 'ask', 'backfill',
                                                'related', 'writeup', 'topic')),
    state       TEXT NOT NULL DEFAULT 'queued'
                  CHECK (state IN ('queued', 'running', 'done', 'dead')),
    failures    INTEGER NOT NULL DEFAULT 0,
    run_after   TEXT NOT NULL,
    last_error  TEXT,
    created_at  TEXT NOT NULL,
    updated_at  TEXT NOT NULL
);

CREATE TABLE enrich_run (
    id             INTEGER PRIMARY KEY,
    page_id        TEXT NOT NULL REFERENCES page(id) ON DELETE CASCADE,
    job_id         INTEGER REFERENCES enrich_job(id) ON DELETE SET NULL,
    model          TEXT NOT NULL,
    served_model   TEXT,
    prompt_version TEXT NOT NULL,
    request        TEXT NOT NULL CHECK (json_valid(request)),
    response       TEXT CHECK (json_valid(response)),
    output         TEXT CHECK (json_valid(output)),
    usage          TEXT CHECK (json_valid(usage)),
    cost_microusd  INTEGER NOT NULL DEFAULT 0,
    status         TEXT NOT NULL DEFAULT 'running'
                     CHECK (status IN ('running', 'ok', 'invalid', 'refused', 'error')),
    error_class    TEXT,
    error          TEXT,
    started_at     TEXT NOT NULL,
    finished_at    TEXT
);

CREATE TABLE enrichment (
    page_id     TEXT PRIMARY KEY REFERENCES page(id) ON DELETE CASCADE,
    run_id      INTEGER REFERENCES enrich_run(id),
    producer    TEXT NOT NULL,
    summary     TEXT NOT NULL DEFAULT '',
    source      TEXT,
    source_title TEXT,
    updated_at  TEXT NOT NULL
);

CREATE TABLE model_tag (
    page_id     TEXT NOT NULL REFERENCES page(id) ON DELETE CASCADE,
    tag         TEXT NOT NULL,
    state       TEXT NOT NULL CHECK (state IN ('on', 'off')),
    producer    TEXT NOT NULL,
    created_at  TEXT NOT NULL,
    PRIMARY KEY (page_id, tag)
);

CREATE TABLE related (
    page_id     TEXT NOT NULL REFERENCES page(id) ON DELETE CASCADE,
    other_id    TEXT NOT NULL REFERENCES page(id) ON DELETE CASCADE,
    rank        INTEGER NOT NULL,
    PRIMARY KEY (page_id, other_id)
);

CREATE TABLE writeup (
    id             INTEGER PRIMARY KEY,
    page_id        TEXT NOT NULL REFERENCES page(id) ON DELETE CASCADE,
    version        INTEGER NOT NULL CHECK (version >= 1),
    producer       TEXT NOT NULL,
    run_id         INTEGER REFERENCES enrich_run(id),
    prompt_version TEXT NOT NULL,
    summary        TEXT NOT NULL DEFAULT '',
    text           TEXT NOT NULL,
    guidance       TEXT,
    restored_from  INTEGER,
    superseded_at  TEXT,
    created_at     TEXT NOT NULL,
    UNIQUE (page_id, version)
);

CREATE TABLE writeup_guidance (
    page_id     TEXT PRIMARY KEY REFERENCES page(id) ON DELETE CASCADE,
    text        TEXT NOT NULL,
    author      TEXT NOT NULL,
    updated_at  TEXT NOT NULL
);

CREATE TABLE topic (
    page_id     TEXT PRIMARY KEY REFERENCES page(id) ON DELETE CASCADE,
    key         TEXT NOT NULL UNIQUE CHECK (length(key) > 0),
    created_at  TEXT NOT NULL
);

CREATE TABLE topic_source (
    topic_id    TEXT NOT NULL REFERENCES topic(page_id) ON DELETE CASCADE,
    page_id     TEXT NOT NULL REFERENCES page(id) ON DELETE CASCADE,
    added_by    TEXT NOT NULL,
    added_at    TEXT NOT NULL,
    excluded    INTEGER NOT NULL DEFAULT 0 CHECK (excluded IN (0, 1)),
    changed_at  TEXT NOT NULL,
    PRIMARY KEY (topic_id, page_id)
);

CREATE TABLE topic_run (
    id             INTEGER PRIMARY KEY,
    model          TEXT NOT NULL,
    served_model   TEXT,
    prompt_version TEXT NOT NULL,
    request        TEXT NOT NULL CHECK (json_valid(request)),
    response       TEXT CHECK (json_valid(response)),
    output         TEXT CHECK (json_valid(output)),
    usage          TEXT CHECK (json_valid(usage)),
    cost_microusd  INTEGER NOT NULL DEFAULT 0,
    status         TEXT NOT NULL DEFAULT 'running'
                     CHECK (status IN ('running', 'ok', 'invalid', 'refused', 'error')),
    error_class    TEXT,
    error          TEXT,
    started_at     TEXT NOT NULL,
    finished_at    TEXT
);

CREATE TABLE page_trash_rev ( id INTEGER PRIMARY KEY AUTOINCREMENT, page_id TEXT NOT NULL REFERENCES page(id) ON DELETE CASCADE, action TEXT NOT NULL CHECK (action IN ('trash', 'restore')), author TEXT NOT NULL, source TEXT NOT NULL CHECK (source IN ('web', 'mcp')), batch_id TEXT, created_at TEXT NOT NULL);

CREATE TABLE page_todo (
    page_id       TEXT PRIMARY KEY REFERENCES page(id) ON DELETE CASCADE,
    due           TEXT CHECK (due IS NULL OR (length(due) = 10 AND date(due) = due)),
    priority      TEXT CHECK (priority IN ('high', 'medium', 'low')),
    snoozed_until TEXT CHECK (snoozed_until IS NULL OR
                      (length(snoozed_until) = 10 AND date(snoozed_until) = snoozed_until)),
    CHECK (due IS NOT NULL OR priority IS NOT NULL OR snoozed_until IS NOT NULL)
) WITHOUT ROWID;

