CREATE INDEX page_meta_rev_by_reverts ON page_meta_rev(reverts);

CREATE INDEX page_meta_rev_by_batch ON page_meta_rev(batch_id);

CREATE UNIQUE INDEX enrich_job_one_queued ON enrich_job(page_id)
    WHERE state = 'queued';

CREATE INDEX enrich_job_ready ON enrich_job(state, run_after);

CREATE INDEX enrich_run_by_started ON enrich_run(started_at);

CREATE INDEX enrich_run_by_page ON enrich_run(page_id);

CREATE INDEX related_by_other ON related(other_id);

CREATE UNIQUE INDEX writeup_current ON writeup(page_id)
    WHERE superseded_at IS NULL;

CREATE INDEX writeup_by_run ON writeup(run_id);

CREATE INDEX topic_source_by_page ON topic_source(page_id);

