CREATE INDEX page_todo_by_snooze ON page_todo(snoozed_until)
    WHERE snoozed_until IS NOT NULL;

CREATE TRIGGER chunk_bu BEFORE UPDATE ON chunk BEGIN
    SELECT RAISE(ABORT, 'chunks are immutable: delete and insert');
END;

CREATE TRIGGER derived_supersede BEFORE INSERT ON derived
WHEN new.superseded_at IS NULL BEGIN
    UPDATE derived SET superseded_at = new.created_at
    WHERE capture_id = new.capture_id AND source_sha256 = new.source_sha256
      AND kind = new.kind AND superseded_at IS NULL;
END;

CREATE TRIGGER derived_immutable BEFORE UPDATE OF capture_id, source_sha256, kind, version,
    producer, run_id, author, text, data, created_at ON derived BEGIN
    SELECT RAISE(ABORT, 'derived versions are immutable: insert a new version');
END;

CREATE TRIGGER derived_once BEFORE UPDATE OF superseded_at ON derived
WHEN old.superseded_at IS NOT NULL BEGIN
    SELECT RAISE(ABORT, 'a superseded version stays superseded: insert a copy to restore it');
END;

CREATE TRIGGER derived_index AFTER INSERT ON derived
WHEN new.superseded_at IS NULL AND coalesce(new.text, '') <> '' BEGIN
    INSERT INTO chunk (page_id, derived_id, ord, text)
    SELECT page_id, new.id, 0, new.text FROM capture WHERE id = new.capture_id;
END;

CREATE TRIGGER derived_unindex AFTER UPDATE OF superseded_at ON derived
WHEN new.superseded_at IS NOT NULL BEGIN
    DELETE FROM chunk WHERE derived_id = new.id;
END;

CREATE TRIGGER chunk_ai AFTER INSERT ON chunk BEGIN
    INSERT INTO chunk_fts(rowid, title, tags, summary, text)
    VALUES (new.id, new.title, new.tags, new.summary, new.text);
END;

CREATE TRIGGER chunk_ad AFTER DELETE ON chunk BEGIN
    INSERT INTO chunk_fts(chunk_fts, rowid, title, tags, summary, text)
    VALUES ('delete', old.id, old.title, old.tags, old.summary, old.text);
END;

CREATE TRIGGER writeup_supersede BEFORE INSERT ON writeup
WHEN new.superseded_at IS NULL BEGIN
    UPDATE writeup SET superseded_at = new.created_at
    WHERE page_id = new.page_id AND superseded_at IS NULL;
END;

CREATE TRIGGER writeup_immutable BEFORE UPDATE OF page_id, version,
    producer, run_id, prompt_version, summary, text, guidance, restored_from,
    created_at ON writeup BEGIN
    SELECT RAISE(ABORT, 'write-up versions are immutable: insert a new version');
END;

CREATE TRIGGER writeup_once BEFORE UPDATE OF superseded_at ON writeup
WHEN old.superseded_at IS NOT NULL BEGIN
    SELECT RAISE(ABORT, 'a superseded version stays superseded: insert a copy');
END;

CREATE TRIGGER page_made_by_fixed BEFORE UPDATE OF made_by ON page
WHEN new.made_by IS NOT old.made_by BEGIN
    SELECT RAISE(ABORT, 'made_by is set when a page is made and never changed');
END;

